	/** 
	 * jumpstart the process by instantiating2 Adjuster
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		adjusterId = AdjusterService.getAdjusterInstance()
		.createAdjuster( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AdjusterService.getAdjusterInstance()
				.createAdjuster( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.adjusterSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Adjuster : " + successValue.getAdjusterId());
							  if (successValue.getAdjusterId().equals(adjusterId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAdjusterList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Adjuster test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on adjuster consumed")
					);
			subscriber.adjusterSubscribe( adjusterId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Adjuster : " + successValue.getAdjusterId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAdjusterList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on adjuster for adjusterId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Adjuster. 
	 */
	protected Adjuster read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Adjuster" );

		Adjuster entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Adjuster with primary key" );
		msg.append( adjusterId );
		
		AdjusterFetchOneSummary fetchOneSummary = new AdjusterFetchOneSummary( adjusterId );

		try {
			entity = AdjusterService.getAdjusterInstance().getAdjuster( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Adjuster " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Adjuster.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Adjuster." );

		StringBuilder msg = new StringBuilder( "Failed to update a Adjuster : " );        
		Adjuster entity = read();
		UpdateAdjusterCommand command = generateUpdateCommand();
		command.setAdjusterId(entity.getAdjusterId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Adjuster." );

			// for use later on...
			adjusterId = entity.getAdjusterId();

			AdjusterService proxy = AdjusterService.getAdjusterInstance();  

			proxy.updateAdjuster( command ).get();

			LOGGER.info( "-- Successfully saved Adjuster - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + adjusterId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Adjuster.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Adjuster." );

		Adjuster entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Adjuster with id " + adjusterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Adjuster with id " + adjusterId );

			throw e;
		}

		try{
			AdjusterService.getAdjusterInstance().delete( new DeleteAdjusterCommand( entity.getAdjusterId() ) ).get();
			LOGGER.info( "-- Successfully deleted Adjuster with id " + adjusterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Adjuster with id " + adjusterId );

			throw e;
		}
	}

	/**
	 * get all Adjusters.
	 */
	protected List<Adjuster> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Adjusters:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Adjuster : " );        
		List<Adjuster> collection  = new ArrayList<>();

		try {
			// call the static get method on the AdjusterService
			collection = AdjusterService.getAdjusterInstance().getAllAdjuster();
			assertNotNull( collection, "An Empty collection of Adjuster was incorrectly returned.");
			
			// Now print out the values
			Adjuster entity = null;            
			Iterator<Adjuster> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAdjusterId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

